// FIX: JSON.parse/stringify pour éviter le bug Proxy n8n
var inp = JSON.parse(JSON.stringify($('Set Target').first().json));
var base = String(inp.website || '').trim().replace(/\/$/, '');
var customPaths = String(inp.custom_page_paths_csv || '')
  .split(',')
  .map(function(v){ return v.trim(); })
  .filter(Boolean);
var defaultPaths = ['/','/a-propos/','/about/','/services/','/solutions/','/expertise/',
  '/produits-et-services/','/products/','/contact/','/carrieres/','/careers/','/blog/'];
function normalizePath(p) {
  if (!p) return '/';
  if (/^https?:\/\//i.test(p)) return p;
  return p.startsWith('/') ? p : '/' + p;
}
var seen = {}; var selectedPaths = [];
customPaths.concat(defaultPaths).forEach(function(p) {
  var n = normalizePath(p);
  if (!seen[n] && selectedPaths.length < 5) { seen[n] = true; selectedPaths.push(n); }
});
var sourcePages = selectedPaths.map(function(p, i) {
  var isAbs = /^https?:\/\//i.test(p);
  var norm  = isAbs ? p : p.replace(/^\/+/, '/');
  var url   = isAbs ? p : base + (norm === '/' ? '' : norm);
  return { key: 'page_' + (i+1), path: isAbs ? null : norm,
           label: isAbs ? 'public_source_' + (i+1) : norm, url: url };
});
var output = Object.assign({}, inp, { source_pages: sourcePages });
sourcePages.forEach(function(p, i) {
  output['page_' + (i+1) + '_url']   = p.url;
  output['page_' + (i+1) + '_label'] = p.label;
});
return [{ json: output }];

// FIX: JSON.parse/stringify pour éviter le bug Proxy n8n
var target = JSON.parse(JSON.stringify($('Build Source URLs').first().json));
var configuredPages = Array.isArray(target.source_pages) ? target.source_pages : [];
var pages = [
  { meta: configuredPages[0] || { key:'page_1', label:'/' },            raw: $('Fetch Public Page 1').first().json },
  { meta: configuredPages[1] || { key:'page_2', label:'/a-propos/' },   raw: $('Fetch Public Page 2').first().json },
  { meta: configuredPages[2] || { key:'page_3', label:'/services/' },   raw: $('Fetch Public Page 3').first().json },
  { meta: configuredPages[3] || { key:'page_4', label:'/solutions/' },  raw: $('Fetch Public Page 4').first().json },
  { meta: configuredPages[4] || { key:'page_5', label:'/contact/' },    raw: $('Fetch Public Page 5').first().json }
];
function toText(raw) {
  var html = (raw && (raw.body || raw.data)) || '';
  return String(html).replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ')
    .replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
}
var pageTexts = pages.map(function(p) {
  return { key: p.meta.key, label: p.meta.label, text: toText(p.raw).slice(0,12000) };
}).filter(function(p){ return p.text; });
var combinedPublicText = pageTexts.map(function(p){ return '['+p.key.toUpperCase()+' - '+p.label+']\n'+p.text; }).join('\n\n');
var normalizedText = combinedPublicText.toLowerCase();
var clueTaxonomy = {
  support_it_intelligent: ['support','helpdesk','incident','ticket','sla','maintenance'],
  service_client_multicanal: ['service client','relation client','support client','contact','crm'],
  machine_contenu_marketing: ['marketing','communication','campagne','contenu','reseaux sociaux'],
  workflow_administratif: ['procedure','validation','reporting','back-office','administratif'],
  assistant_direction_documentaire: ['direction','rapport','compte rendu','documentation','pilotage'],
  reporting_financier_assiste: ['finance','facturation','comptabilite','recouvrement','paiement'],
  recrutement_onboarding_augmente: ['recrutement','talent','carriere','onboarding','rh'],
  telemedecine_triage_orientation: ['sante','patient','clinique','hopital','telemedecine'],
  banque_kyc_reporting: ['banque','kyc','conformite','compliance','risque'],
  operations_terrain_coordination: ['terrain','flotte','logistique','livraison','intervention','operations']
};
var roiClues = Object.keys(clueTaxonomy).filter(function(key){
  return clueTaxonomy[key].some(function(kw){ return normalizedText.indexOf(kw) !== -1; });
});
return [{ json: Object.assign({}, target, {
  page_texts: pageTexts,
  public_text: combinedPublicText.slice(0,45000),
  roi_clues: roiClues.length ? roiClues : ['workflow_administratif','service_client_multicanal','assistant_direction_documentaire']
}) }];

// FIX: JSON.parse/stringify pour éviter le bug Proxy n8n
var source = JSON.parse(JSON.stringify($input.first().json));
var orgName = (source.organization_name || '').trim();
var decisionMaker = (source.decision_maker_name || '').trim();
var website = (source.website || '').trim();
var domain = website.replace(/^https?:\/\//i,'').replace(/^www\./i,'').split('/')[0];

function escapeRegex(v){ return v.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }

var sanitizedText = String(source.public_text || '');
var genericPatterns = [
  [/https?:\/\/\S+/gi,'[URL_REDACTED]'],
  [/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,'[EMAIL_REDACTED]'],
  [/\+?\d[\d\s().-]{7,}\d/g,'[PHONE_REDACTED]']
];
for(var i=0;i<genericPatterns.length;i++) sanitizedText=sanitizedText.replace(genericPatterns[i][0],genericPatterns[i][1]);

var sensitiveTokens=[
  {value:orgName,replacement:'ORG_TARGET'},
  {value:decisionMaker,replacement:'DECISION_MAKER_TARGET'},
  {value:domain,replacement:'[URL_REDACTED]'}
].filter(function(t){return t.value&&t.value.length>2;});
for(var j=0;j<sensitiveTokens.length;j++){
  var pat=new RegExp(escapeRegex(sensitiveTokens[j].value),'gi');
  sanitizedText=sanitizedText.replace(pat,sensitiveTokens[j].replacement);
}

var normalized=sanitizedText.toLowerCase();

// 13 SECTEURS STRATEGIQUES TRANSFERAI
var signalTaxonomy={
  support_it_intelligent:{
    keywords:['support','helpdesk','incident','ticket','sla','maintenance'],
    pitch:'optimisation du support IT et gestion des incidents par IA'
  },
  service_client_multicanal:{
    keywords:['service client','relation client','support client','contact center','crm'],
    pitch:'transformation du service client multicanal avec agents IA'
  },
  machine_contenu_marketing:{
    keywords:['marketing','communication','campagne','contenu','marque','reseaux sociaux'],
    pitch:'generation automatisee de contenu marketing personnalise'
  },
  workflow_administratif:{
    keywords:['procedure','validation','reporting','back-office','administratif'],
    pitch:'automatisation des workflows administratifs et back-office'
  },
  assistant_direction_documentaire:{
    keywords:['direction','pilotage','rapport','documentation','compte rendu'],
    pitch:'assistant IA pour la direction et la gestion documentaire'
  },
  reporting_financier_assiste:{
    keywords:['facturation','finance','comptabilite','paiement','recouvrement'],
    pitch:'reporting financier automatise et suivi comptable par IA'
  },
  recrutement_onboarding_augmente:{
    keywords:['recrutement','carriere','rh','talent','onboarding'],
    pitch:'recrutement augmente et onboarding automatise par IA'
  },
  commentaire_donnees_reporting:{
    keywords:['donnees','dashboard','analytics','indicateurs','tableau de bord'],
    pitch:'analyse et commentaire automatique des donnees et KPIs'
  },
  telemedecine_triage_orientation:{
    keywords:['sante','patient','clinique','hopital','telemedecine'],
    pitch:'triage intelligent et orientation patient par IA medicale'
  },
  banque_kyc_reporting:{
    keywords:['banque','kyc','compliance','conformite','risque'],
    pitch:'automatisation KYC, conformite et reporting bancaire par IA'
  },
  operations_terrain_coordination:{
    keywords:['flotte','terrain','logistique','livraison','intervention','operations'],
    pitch:'coordination des operations terrain et gestion de flotte par IA'
  },
  energie_industrie_services:{
    keywords:['energie','oil','gas','station','industrie','industriel'],
    pitch:'optimisation des processus industriels et energetiques par IA'
  },
  formation_montee_en_competence:{
    keywords:['formation','certification','academy','apprentissage','competence'],
    pitch:'formation acceleree et montee en competence assistee par IA'
  }
};

// DETECTION AUTOMATIQUE NOUVEAUX SECTEURS
var genericSectorKeywords={
  agriculture:['agriculture','farming','recolte','irrigation','elevage'],
  tourisme:['tourisme','hotel','reservation','voyage','hospitality'],
  immobilier:['immobilier','foncier','location','promotion','construction'],
  transport:['transport','mobilite','conducteur','passager','trajet'],
  education:['ecole','universite','enseignement','etudiant','pedagogie'],
  retail:['commerce','vente','magasin','stock','caisse'],
  telecom:['telecom','operateur','reseau','connectivite','mobile'],
  assurance:['assurance','sinistre','police','prime','indemnisation'],
  juridique:['juridique','legal','contrat','avocat','tribunal'],
  media:['media','presse','radio','television','journalisme']
};

var detectedSectors=[];
var sectorPitches=[];

Object.keys(signalTaxonomy).forEach(function(key){
  var found=signalTaxonomy[key].keywords.some(function(kw){return normalized.indexOf(kw)!==-1;});
  if(found){
    detectedSectors.push(key);
    sectorPitches.push(signalTaxonomy[key].pitch);
  }
});

var isNewSector=false;
var newSectorName='';
if(detectedSectors.length===0){
  Object.keys(genericSectorKeywords).forEach(function(key){
    var found=genericSectorKeywords[key].some(function(kw){return normalized.indexOf(kw)!==-1;});
    if(found && !isNewSector){
      isNewSector=true;
      newSectorName=key;
      detectedSectors.push('nouveau_secteur_'+key);
      sectorPitches.push("application de l'IA aux processus specifiques du secteur "+key);
    }
  });
}

if(detectedSectors.length===0){
  detectedSectors=['workflow_administratif','assistant_direction_documentaire'];
  sectorPitches=['automatisation des processus metier par IA'];
}

// DETECTION LANGUE PAR TLD + TEXTE
var websiteDomain = String(source.website || '').toLowerCase();
var tld = websiteDomain.replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0].split('.').pop();

var frenchTlds = ['ci','sn','ml','bf','bj','tg','cd','cg','ga','cm','mg','tn','ma','dz','gn','ne','td','cf','km','bi','rw','fr','be','ch','lu','mc'];
var englishTlds = ['uk','gh','ng','ke','tz','za','zw','ug','us','au','nz','ie','in','sg','my'];
var spanishTlds = ['es','mx','co','ar','pe','cl','ve','ec','uy','py','bo','cr','gt','hn','ni','pa','do','cu','pr'];

var detectedLanguage = 'fr';

if(frenchTlds.indexOf(tld) !== -1){
  detectedLanguage = 'fr';
} else if(englishTlds.indexOf(tld) !== -1){
  detectedLanguage = 'en';
} else if(spanishTlds.indexOf(tld) !== -1){
  detectedLanguage = 'es';
} else {
  // TLD neutre (.com .org .net) → analyser le texte
  var langDetectionText = normalized.slice(0, 2000);
  var frenchSignals = ['les','des','pour','avec','nous','votre','notre','vous','est','une','dans'];
  var englishSignals = ['the','and','for','with','our','your','we','are','this','that','have'];
  var spanishSignals = ['los','las','para','con','nuestro','vuestra','somos','este','tiene','una'];
  function countSignals(signals, text){
    return signals.filter(function(w){ return text.indexOf(' '+w+' ') !== -1; }).length;
  }
  var frScore = countSignals(frenchSignals, langDetectionText);
  var enScore = countSignals(englishSignals, langDetectionText);
  var esScore = countSignals(spanishSignals, langDetectionText);
  if(enScore > frScore && enScore > esScore) detectedLanguage = 'en';
  if(esScore > frScore && esScore > enScore) detectedLanguage = 'es';
}

// Priorite a la langue forcee manuellement
var finalLanguage = source.prospect_language && source.prospect_language !== 'auto'
  ? source.prospect_language
  : detectedLanguage;

var languageInstructions = {
  'fr': 'Redige UNIQUEMENT en francais standard avec accents.',
  'en': 'Write ONLY in standard English with proper grammar.',
  'es': 'Redacta UNICAMENTE en espanol estandar con acentos.'
};

// CONSTRUCTION PAYLOAD LLM
var llmAllowedPayload={
  llm_policy:'deny-by-default',
  organization_ref:'ORG_TARGET',
  decision_maker_ref:decisionMaker?'DECISION_MAKER_TARGET':null,
  organization_type:source.organization_type||null,
  sector_guess:source.sector_guess||null,
  country:source.country||null,
  signal_tags:detectedSectors,
  sector_pitches:sectorPitches,
  is_new_sector:isNewSector,
  new_sector_name:newSectorName||null,
  roi_clues:Array.isArray(source.roi_clues)?source.roi_clues:[],
  page_keys:Array.isArray(source.page_texts)?source.page_texts.map(function(p){return p.key;}):[],
  public_text_sanitized_excerpt:sanitizedText.slice(0,12000),
  strategic_sectors_coverage:'13 secteurs strategiques TransferAI + detection automatique nouveaux secteurs',
  language:finalLanguage,
  language_instruction:languageInstructions[finalLanguage],
  detected_tld:tld
};

var llmGenerationPayload=Object.assign({},llmAllowedPayload,{
  organization_display:'{{ORGANIZATION_NAME}}',
  decision_maker_display:'{{DECISION_MAKER_NAME}}',
  website_display:'{{WEBSITE}}'
});

return [{ json: Object.assign({},source,{
  public_text_sanitized:sanitizedText.slice(0,12000),
  signal_tags:detectedSectors,
  sector_pitches:sectorPitches,
  is_new_sector:isNewSector,
  detected_language:finalLanguage,
  detected_tld:tld,
  llm_allowed_payload:llmAllowedPayload,
  llm_generation_payload:llmGenerationPayload,
  llm_redaction_summary:{
    policy:'deny-by-default',
    strategic_sectors:Object.keys(signalTaxonomy),
    detected_sectors:detectedSectors,
    is_new_sector:isNewSector,
    language:finalLanguage,
    tld:tld
  }
}) }];

var base = JSON.parse(JSON.stringify($('Sanitize Prospect Data For LLM').first().json));

function parseOpenAI(nodeName) {
  try {
    var n = $(nodeName).first().json;
    var raw = (n && n.choices && n.choices[0] && n.choices[0].message && n.choices[0].message.content) || '{}';
    try { return JSON.parse(raw); } catch (e) { return { parse_error: nodeName + ': ' + e.message }; }
  } catch (e) { return { parse_error: nodeName + ': not executed' }; }
}

function slugify(v) {
  return String(v || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

var SECTOR_NORM = {
  finance: 'finance_comptabilite', comptabilite: 'finance_comptabilite', accounting: 'finance_comptabilite', budget: 'finance_comptabilite',
  service_client: 'service_client', customer: 'service_client', support: 'service_client', crm: 'service_client', call_center: 'service_client',
  rh: 'ressources_humaines', ressources_humaines: 'ressources_humaines', recrutement: 'ressources_humaines', hr: 'ressources_humaines',
  it: 'it_transformation_digitale', digital: 'it_transformation_digitale', cloud: 'it_transformation_digitale', informatique: 'it_transformation_digitale',
  marketing: 'marketing_communication', communication: 'marketing_communication',
  energie: 'energie_petrole', oil: 'energie_petrole', gas: 'energie_petrole', industrie: 'energie_petrole',
  juridique: 'juridique_conformite', legal: 'juridique_conformite', conformite: 'juridique_conformite', kyc: 'juridique_conformite',
  sante: 'sante_bien_etre', health: 'sante_bien_etre', medical: 'sante_bien_etre',
  administration: 'administration_gestion', gestion: 'administration_gestion', workflow: 'administration_gestion',
  transport: 'transport_logistique', logistique: 'transport_logistique', flotte: 'transport_logistique',
  management: 'management_leadership', direction: 'management_leadership', leadership: 'management_leadership',
  formation: 'formation_pedagogie', pedagogie: 'formation_pedagogie', academie: 'formation_pedagogie',
  data: 'data_analyse', analytics: 'data_analyse', dashboard: 'data_analyse',
  telecom: 'telecommunications', operateur: 'telecommunications',
  assistanat: 'assistanat_secretariat', secretariat: 'assistanat_secretariat',
  diplomatie: 'diplomatie_affaires_internationales'
};

function normalizeSectorVariant(raw) {
  if (!raw) return 'multi_sector_operations';
  var s = slugify(raw);
  if (SECTOR_NORM[s]) return SECTOR_NORM[s];
  var keys = Object.keys(SECTOR_NORM);
  for (var i = 0; i < keys.length; i++) {
    if (s.indexOf(keys[i]) !== -1) return SECTOR_NORM[keys[i]];
  }
  return s || 'multi_sector_operations';
}

var CTA_BY_LANG = {
  'fr': "Planifier un audit stratégique gratuit et un rendez-vous expert de 30 minutes",
  'en': "Schedule a free strategic audit and a 30-minute expert meeting",
  'es': "Agendar una auditoría estratégica gratuita y una reunión experta de 30 minutos"
};

var preAudit = parseOpenAI('Call OpenAI Pre-Audit');
var problems = parseOpenAI('Call OpenAI Problems Solutions');
var roi      = parseOpenAI('Call OpenAI ROI');

var bookingLink = base.booking_link_30min || base.booking_link_45min || 'https://calendly.com/contact-transferai/30min';
var detectedLang = base.detected_language || preAudit.detected_language_hint || 'fr';
var finalLang = (detectedLang === 'en' || detectedLang === 'es') ? detectedLang : 'fr';

var rawSector = problems.sector_variant || preAudit.sector_variant || base.sector_guess || '';
var sectorVariant = normalizeSectorVariant(rawSector);

return [{ json: Object.assign({}, base, preAudit, problems, roi, {
  booking_link_30min: bookingLink,
  booking_link_45min: bookingLink,
  prospect_language: finalLang,
  detected_language: finalLang,
  single_primary_cta: CTA_BY_LANG[finalLang] || CTA_BY_LANG['fr'],
  sector_variant: sectorVariant
}) }];

var ctx = JSON.parse(JSON.stringify($('Assemble Prospect Context').first().json));

function textFrom(nodeName) {
  try {
    var node = $(nodeName).first().json;
    return (node && node.choices && node.choices[0] && node.choices[0].message && node.choices[0].message.content) || '';
  } catch (e) {
    return '';
  }
}

function jsonFrom(nodeName) {
  var raw = textFrom(nodeName) || '{}';
  try {
    return JSON.parse(raw);
  } catch (e) {
    return {
      parse_error: nodeName + ': ' + e.message,
      raw: raw
    };
  }
}

function hydrateString(value, ctx) {
  return String(value)
    .split('{{ORGANIZATION_NAME}}').join(ctx.organization_name || '')
    .split('{{DECISION_MAKER_NAME}}').join(ctx.decision_maker_name || '')
    .split('{{WEBSITE}}').join(ctx.website || '');
}

function hydrateValue(value, ctx) {
  if (typeof value === 'string') return hydrateString(value, ctx);
  if (Array.isArray(value)) {
    return value.map(function(item) {
      return hydrateValue(item, ctx);
    });
  }
  if (value && typeof value === 'object') {
    var out = {};
    var keys = Object.keys(value);
    for (var i = 0; i < keys.length; i++) {
      out[keys[i]] = hydrateValue(value[keys[i]], ctx);
    }
    return out;
  }
  return value;
}

var executiveLetter = hydrateString(textFrom('Generate Executive Letter'), ctx);
var tailoredCatalogue = hydrateString(textFrom('Generate Tailored Catalogue'), ctx);
var tailoredAuditForm = hydrateString(textFrom('Generate Tailored Audit Form'), ctx);
var deckBrief = hydrateValue(jsonFrom('Generate Deck Brief'), ctx);

var requiresEmail = Object.prototype.hasOwnProperty.call(ctx, 'target_email');
var approvedForSend = Boolean(
  ctx.organization_name &&
  ctx.entry_point_niche &&
  ctx.recommended_offer &&
  (!requiresEmail || ctx.target_email)
);

var packId = ctx.pack_id || ('pack-' + Date.now() + '-' + Math.random().toString(36).slice(2, 10));
var auditBaseUrl = String(ctx.audit_form_base_url || 'https://www.transferai.ci/questionnaire-audit').trim();
var rawAuditSuffix = String(ctx.audit_form_query_suffix || '').trim();
var cleanAuditSuffix = rawAuditSuffix.replace(/^[?&]+/, '');
var auditFormUrl = String(ctx.audit_form_url || '').trim();

if (!auditFormUrl) {
  auditFormUrl = auditBaseUrl + (auditBaseUrl.indexOf('?') >= 0 ? '&' : '?') + 'pack_id=' + encodeURIComponent(packId);
  if (cleanAuditSuffix) {
    auditFormUrl += '&' + cleanAuditSuffix;
  }
}

var executiveLetterHtml = executiveLetter.replace(/\n/g, '<br>');

return [
  {
    json: {
      prospect_id: ctx.prospect_id || null,
      organization_name: ctx.organization_name || '',
      decision_maker_name: ctx.decision_maker_name || '',
      website: ctx.website || '',
      country: ctx.country || '',
      target_email: ctx.target_email || '',
      organization_type: ctx.organization_type || '',
      sector_guess: ctx.sector_guess || '',
      pack_id: packId,
      audit_form_base_url: auditBaseUrl,
      audit_form_query_suffix: rawAuditSuffix,
      audit_form_url: auditFormUrl,
      executive_letter: executiveLetter,
      executive_letter_html: executiveLetterHtml,
      tailored_catalogue: tailoredCatalogue,
      tailored_audit_form: tailoredAuditForm,
      deck_brief: deckBrief,
      approved_for_send: approvedForSend,
      source_backend: ctx.source_backend || 'manual',
      source_label: ctx.source_label || '',
      raw_source_id: ctx.raw_source_id || '',
      llm_redaction_summary: ctx.llm_redaction_summary,
      llm_allowed_payload: ctx.llm_allowed_payload,
      llm_generation_payload: ctx.llm_generation_payload,
      probable_needs: ctx.probable_needs || [],
      probable_problems: ctx.probable_problems || [],
      probable_quick_wins: ctx.probable_quick_wins || [],
      recommended_offer: ctx.recommended_offer || '',
      recommended_use_case: ctx.recommended_use_case || '',
      best_selling_use_case: ctx.best_selling_use_case || '',
      commercial_priority_tier: ctx.commercial_priority_tier || ctx.commercial_priority_default || '',
      roi_hypothesis: ctx.roi_hypothesis || [],
      expected_time_savings: ctx.expected_time_savings || [],
      expected_service_improvements: ctx.expected_service_improvements || [],
      expected_quick_wins: ctx.expected_quick_wins || [],
      delivery_timeline: ctx.delivery_timeline || [],
      recommended_training_bundle: ctx.recommended_training_bundle || [],
      sector_pitches: ctx.sector_pitches || [],
      signal_tags: (ctx.llm_allowed_payload && ctx.llm_allowed_payload.signal_tags) || []
    }
  }
];

