  : Array.isArray($json.data)
    ? $json.data
    : Array.isArray($json.body)
      ? $json.body
      : [];

const row = rows[0] || {};
const payload = row.payload || {};
const decision = $('Parse Approval Query').first().json.decision;

const executiveLetterHtml = String(
  payload.executive_letter_html || payload.executive_letter || ''
).split('\n').join('<br>');

return [{
